export async function reserveStock(req: ReserveRequest, deadline: number): Promise<Reservation> {
  const maxAttempts = 4;
  for (let attempt = 0; ; attempt++) {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), 5_000); //!issue:2
    try {
      const res = await fetch(`${INVENTORY_URL}/reservations`, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify(req), //!issue:4
        signal: ctrl.signal,
      });
      if (res.ok) return (await res.json()) as Reservation;
      if (attempt + 1 >= maxAttempts) throw new HttpError(res.status); //!issue:1
    } catch (err) {
      if (attempt + 1 >= maxAttempts) throw err;
    } finally {
      clearTimeout(timer);
    }
    await sleep(100 * 2 ** attempt); //!issue:3
  }
}

