func ReserveStock(ctx context.Context, req ReserveRequest) (*Reservation, error) {
	body, err := json.Marshal(req)
	if err != nil {
		return nil, err
	}
	var lastErr error
	for attempt := 0; attempt < 4; attempt++ {
		attemptCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second) //!issue:2
		httpReq, err := http.NewRequestWithContext(attemptCtx, http.MethodPost, inventoryURL+"/reservations", bytes.NewReader(body)) //!issue:4
		if err != nil {
			cancel()
			return nil, err
		}
		httpReq.Header.Set("Content-Type", "application/json")
		resp, err := client.Do(httpReq)
		if err == nil {
			if resp.StatusCode < 300 {
				var out Reservation
				err = json.NewDecoder(resp.Body).Decode(&out)
				resp.Body.Close()
				cancel()
				return &out, err
			}
			resp.Body.Close()
			err = fmt.Errorf("inventory: status %d", resp.StatusCode) //!issue:1
		}
		cancel()
		lastErr = err
		time.Sleep(time.Duration(100<<attempt) * time.Millisecond) //!issue:3
	}
	return nil, lastErr
}

