func (b *Breaker) Call(fn func() error) error {
	b.mu.Lock()
	if b.state == Open {
		if time.Since(b.openedAt) < b.cooldown {
			b.mu.Unlock()
			return ErrOpen
		}
		b.state = HalfOpen //!issue:2
	}
	b.mu.Unlock()

	err := fn() //!issue:4

	b.mu.Lock()
	defer b.mu.Unlock()
	if err == nil {
		b.state = Closed //!issue:1
		return nil
	}
	b.failures++ //!issue:3
	if b.failures >= b.threshold {
		b.state = Open
		b.openedAt = time.Now()
	}
	return err
}

