pub struct Breaker {
    inner: Mutex<Inner>,
    threshold: u32,
    cooldown: Duration,
}

struct Inner {
    state: State,
    failures: u32,
    opened_at: Instant,
}

impl Breaker {
    pub async fn call<T, E, F, Fut>(&self, f: F) -> Result<T, BreakerError<E>>
    where
        F: FnOnce() -> Fut,
        Fut: Future<Output = Result<T, E>>,
    {
        {
            let mut s = self.inner.lock().unwrap();
            if s.state == State::Open {
                if s.opened_at.elapsed() < self.cooldown {
                    return Err(BreakerError::Open);
                }
                s.state = State::HalfOpen; //!issue:2
            }
        }
        let result = f().await; //!issue:4
        let mut s = self.inner.lock().unwrap();
        match result {
            Ok(v) => {
                s.state = State::Closed; //!issue:1
                Ok(v)
            }
            Err(e) => {
                s.failures += 1; //!issue:3
                if s.failures >= self.threshold {
                    s.state = State::Open;
                    s.opened_at = Instant::now();
                }
                Err(BreakerError::Inner(e))
            }
        }
    }
}

