public sealed class CircuitBreaker
{
    private readonly object _gate = new();
    private readonly int _threshold;
    private readonly TimeSpan _cooldown;
    private State _state = State.Closed;
    private int _failures;
    private DateTime _openedAt;

    public CircuitBreaker(int threshold, TimeSpan cooldown) => (_threshold, _cooldown) = (threshold, cooldown);

    public async Task<T> CallAsync<T>(Func<Task<T>> fn)
    {
        lock (_gate)
        {
            if (_state == State.Open)
            {
                if (DateTime.UtcNow - _openedAt < _cooldown)
                    throw new CircuitOpenException();
                _state = State.HalfOpen; //!issue:2
            }
        }
        try
        {
            var result = await fn(); //!issue:4
            lock (_gate) { _state = State.Closed; } //!issue:1
            return result;
        }
        catch (Exception)
        {
            lock (_gate)
            {
                _failures++; //!issue:3
                if (_failures >= _threshold)
                {
                    _state = State.Open;
                    _openedAt = DateTime.UtcNow;
                }
            }
            throw;
        }
    }
}

