public final class CircuitBreaker {
    private enum State { CLOSED, OPEN, HALF_OPEN }

    private final int threshold;
    private final Duration cooldown;
    private State state = State.CLOSED;
    private int failures;
    private Instant openedAt = Instant.EPOCH;

    public CircuitBreaker(int threshold, Duration cooldown) {
        this.threshold = threshold;
        this.cooldown = cooldown;
    }

    public <T> T call(Callable<T> fn) throws Exception {
        synchronized (this) {
            if (state == State.OPEN) {
                if (Duration.between(openedAt, Instant.now()).compareTo(cooldown) < 0) {
                    throw new CircuitOpenException();
                }
                state = State.HALF_OPEN; //!issue:2
            }
        }
        try {
            T result = fn.call(); //!issue:4
            synchronized (this) { state = State.CLOSED; } //!issue:1
            return result;
        } catch (Exception e) {
            synchronized (this) {
                failures++; //!issue:3
                if (failures >= threshold) {
                    state = State.OPEN;
                    openedAt = Instant.now();
                }
            }
            throw e;
        }
    }
}
